import json,hashlib
from pathlib import Path
from collections import Counter
root=Path('incident/dataset');src=Path('loader.py').read_text();ns={}
exec(compile(src,'loader.py','exec'),ns)
rows=json.loads((root/'manifest.json').read_text())['rows'];out=Counter()
for row in rows:
 path=ns['resolve'](root,row)
 out[(row['difficulty'],'present' if (root/path).is_file() else 'missing')]+=1
print('received resolver SHA256:',hashlib.sha256(src.encode()).hexdigest())
print('received resolver results:',dict(out))
for label,probe in [('unknown hash, existing path',dict(rows[0],sha256='0'*64)),('unknown hash, missing path',dict(rows[1],sha256='0'*64))]:
 try:
  p=ns['resolve'](root,probe);print('unavailability probe:',label,'incorrectly returns',p)
 except (FileNotFoundError,ValueError):print('unavailability probe:',label,'correctly raised')
