import json,hashlib
from pathlib import Path
from collections import Counter
root=Path('incident/dataset');case=json.loads((root/'CASE.json').read_text());catalog=json.loads((root/'catalog.json').read_text())['rows']
content={r['id']:json.loads((root/r['path']).read_text()) for r in catalog}
content.update({r['id']:r for r in map(json.loads,(root/'eval.jsonl').read_text().splitlines())})
selected={}
for r in case['rows']:selected.setdefault(Path(r['public_file']).name,{})[r['row_index_0based']]=r
checked=Counter();failures=[]
for name,indices in selected.items():
 for i,line in enumerate((Path('public-source')/name).open()):
  if i not in indices:continue
  r=indices[i]; public=json.loads(line); data=content[r['id']]
  tests={'id': data['id']==r['id'], 'prompt': data['prompt']==[{'role':'user','content':public['query']}], 'label':data['label']==str(public['ground_truth']), 'difficulty': data['metadata']['difficulty']==r['difficulty'], 'source_line':data['metadata']['source_line']==r['source_line']}
  for k,ok in tests.items():
   if not ok:failures.append((r['id'],k))
  checked[r['split']]+=1
print('public source content comparisons:',dict(checked),'mismatches:',failures)
train_ids={r['id'] for r in catalog};eval_ids={json.loads(s)['id'] for s in (root/'eval.jsonl').read_text().splitlines()}
print('train/eval identities overlap:',len(train_ids & eval_ids))
